import React, { useRef, useState } from 'react';
import { useSpeechSettings } from '../hooks/useSpeechSettings';
import { useGlobalAudioContext } from '../contexts/GlobalAudioContext';

interface SimulationControlsProps {
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme';
  onAdvancePhase: (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => void;
  onReset: () => void;
  nortonEscalation?: boolean; // Norton escalation state
}

const SimulationControls: React.FC<SimulationControlsProps> = ({
  currentPhase,
  onAdvancePhase,
  onReset,
  nortonEscalation = false // Norton escalation state
}) => {
  const { isMuted, toggleMuted } = useSpeechSettings();
  const { isPlaying, toggleSpeech } = useGlobalAudioContext();

  const phases = [
    { id: 'norton', name: 'Norton', color: '#ff6b35' },
    { id: 'microsoft', name: 'Microsoft', color: '#0078d4' },
    { id: 'google', name: 'Google', color: '#4285f4' },
    { id: 'malwarebytes', name: 'Malwarebytes', color: '#00a651' },
    { id: 'generic', name: 'Legal Threats', color: '#ff0000' },
    { id: 'advanced', name: 'Tech Support', color: '#8b0000' },
    { id: 'extreme', name: 'Ransomware', color: '#8b0000' }
  ];

  const currentPhaseIndex = phases.findIndex(phase => phase.id === currentPhase);

  // --- Drag and Drop State ---
  const [position, setPosition] = useState({ top: 20, left: window.innerWidth - 340 });
  const [dragging, setDragging] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const dragOffset = useRef({ x: 0, y: 0 });

  // Debug state for click detection
  const [debugClicks, setDebugClicks] = useState<Array<{x: number, y: number, timestamp: number}>>([]);

  // Add global click listener for debugging
  React.useEffect(() => {
    const handleGlobalClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const isSimulationControl = target.closest('.simulation-controls');

      if (!isSimulationControl) {
        setDebugClicks(prev => [...prev.slice(-10), {
          x: e.clientX,
          y: e.clientY,
          timestamp: Date.now()
        }]);
      }
    };

    document.addEventListener('click', handleGlobalClick);
    return () => document.removeEventListener('click', handleGlobalClick);
  }, []);

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement> | React.TouchEvent<HTMLDivElement>) => {
    // Don't start dragging if clicking on interactive elements
    const target = e.target as HTMLElement;
    if (target.tagName === 'BUTTON' || target.closest('button') || target.closest('[data-no-drag]')) {
      return;
    }

    setDragging(true);
    let clientX: number, clientY: number;
    if ('touches' in e && e.touches.length > 0) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else if ('clientX' in e) {
      clientX = e.clientX;
      clientY = e.clientY;
    } else {
      return;
    }
    dragOffset.current = {
      x: clientX - position.left,
      y: clientY - position.top
    };
    document.body.style.userSelect = 'none';
  };

  React.useEffect(() => {
    const handleMouseMove = (e: MouseEvent | TouchEvent) => {
      if (!dragging) return;
      let clientX: number, clientY: number;
      if ('touches' in e && (e as TouchEvent).touches.length > 0) {
        clientX = (e as TouchEvent).touches[0].clientX;
        clientY = (e as TouchEvent).touches[0].clientY;
      } else if ('clientX' in e) {
        clientX = (e as MouseEvent).clientX;
        clientY = (e as MouseEvent).clientY;
      } else {
        return;
      }
      setPosition(pos => ({
        top: Math.max(0, Math.min(window.innerHeight - 80, clientY - dragOffset.current.y)),
        left: Math.max(0, Math.min(window.innerWidth - 320, clientX - dragOffset.current.x))
      }));
    };
    const handleMouseUp = () => {
      setDragging(false);
      document.body.style.userSelect = '';
    };

    // Handle window resize to keep controls in viewport
    const handleResize = () => {
      setPosition(pos => ({
        top: Math.max(0, Math.min(window.innerHeight - 80, pos.top)),
        left: Math.max(0, Math.min(window.innerWidth - 320, pos.left))
      }));
    };

    if (dragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('touchmove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchend', handleMouseUp);
    }

    // Add resize listener
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('touchend', handleMouseUp);
      window.removeEventListener('resize', handleResize);
    };
  }, [dragging]);

  return (
    <div 
      className="simulation-controls dark-mode"
      style={{
        position: 'fixed',
        top: position.top,
        left: position.left,
        background: 'rgba(45, 45, 45, 0.95)',
        border: '3px solid #007bff',
        borderRadius: '12px',
        padding: collapsed ? '0.5rem' : '1.5rem',
        zIndex: 99999,
        boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        backdropFilter: 'blur(10px)',
        minWidth: '300px',
        maxWidth: '400px',
        cursor: dragging ? 'grabbing' : 'default',
        userSelect: dragging ? 'none' : 'auto',
        transition: dragging ? 'none' : 'box-shadow 0.2s',
        pointerEvents: 'auto',
        isolation: 'isolate'
      }}

    >
      <div 
        style={{ 
          textAlign: 'center', 
          marginBottom: collapsed ? '0' : '1rem',
          borderBottom: collapsed ? 'none' : '2px solid #007bff',
          paddingBottom: collapsed ? '0' : '0.5rem',
          cursor: 'grab',
          userSelect: 'none',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          pointerEvents: 'auto',
          position: 'relative',
          zIndex: 99999
        }}
        onMouseDown={handleMouseDown}
        onTouchStart={handleMouseDown}
      >
        <div style={{ flex: 1 }}>
          <h3 style={{ 
            margin: 0, 
            color: '#007bff', 
            fontSize: '1.2rem',
            fontWeight: 'bold',
            pointerEvents: 'none'
          }}>
            🎮 Simulation Controls
          </h3>
          {!collapsed && (
            <div style={{ 
              fontSize: '0.9rem', 
              color: '#b0b0b0',
              marginTop: '0.25rem',
              pointerEvents: 'none'
            }}>
              Protected from browser hijacking
            </div>
          )}
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation();
            setCollapsed(!collapsed);
          }}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            color: '#007bff',
            padding: '0.25rem',
            borderRadius: '4px',
            transition: 'background-color 0.2s',
            marginLeft: '0.5rem'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = 'rgba(0, 123, 255, 0.1)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent';
          }}
          title={collapsed ? 'Expand Controls' : 'Collapse Controls'}
        >
          {collapsed ? '▶' : '▼'}
        </button>
      </div>

      {!collapsed && (
        <>
          <div style={{ marginBottom: '1rem' }}>
        <div style={{ 
          fontSize: '0.9rem', 
          fontWeight: 'bold', 
          marginBottom: '0.5rem',
          color: '#ffffff'
        }}>
          Current Scareware: {phases[currentPhaseIndex]?.name}
        </div>
        <div style={{ 
          fontSize: '0.8rem', 
          color: '#ff6b6b',
          marginBottom: '0.5rem'
        }}>
          Debug: {phases.length} phases, current index: {currentPhaseIndex}
        </div>
        <div style={{ 
          display: 'flex', 
          gap: '0.25rem',
          flexWrap: 'wrap',
          position: 'relative',
          zIndex: 99999,
          padding: '2px',
          background: 'rgba(255, 0, 0, 0.1)',
          borderRadius: '4px',
          minHeight: '32px'
        }}>
          {phases.map((phase, index) => {
            console.log(`🎮 Rendering button ${index + 1} for phase: ${phase.id}`);
            return (
            <div
              key={phase.id}
              data-no-drag="true"
              data-button-index={index}
              data-button-number={index + 1}
              style={{
                width: '28px',
                height: '28px',
                borderRadius: '50%',
                backgroundColor: phase.id === currentPhase ? phase.color : '#404040',
                border: phase.id === currentPhase ? '2px solid #ffffff' : '1px solid #666',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '0.7rem',
                color: phase.id === currentPhase ? 'white' : '#b0b0b0',
                fontWeight: 'bold',
                position: 'relative',
                zIndex: 100000,
                userSelect: 'none',
                padding: '2px',
                boxSizing: 'border-box',
                minWidth: '28px',
                minHeight: '28px',
                // Special styling for button 1 to make it more visible
                ...(index === 0 && {
                  border: '2px solid #ff0000',
                  boxShadow: '0 0 5px #ff0000'
                })
              }}
              onClick={(e) => {
                e.stopPropagation();
                e.preventDefault();
                console.log(`🎮 SimulationControls: Number button ${index + 1} clicked for phase: ${phase.id}`);
                console.log(`🎮 Button details:`, { index, phaseId: phase.id, buttonNumber: index + 1 });
                onAdvancePhase(phase.id as any);
              }}
              onMouseDown={(e) => {
                e.stopPropagation();
                console.log(`🎮 Mouse down on button ${index + 1}`);
              }}
              onMouseEnter={(e) => {
                console.log(`🎮 Mouse enter on button ${index + 1}`);
              }}
              onTouchStart={(e) => {
                e.stopPropagation();
                console.log(`🎮 Touch start on button ${index + 1}`);
              }}
              title={`${phase.name} (${index + 1}/${phases.length})`}
            >
              {index + 1}
            </div>
          )})}
        </div>
      </div>

      <div style={{ 
        display: 'flex', 
        gap: '0.5rem',
        flexWrap: 'wrap'
      }}>
        <button
          onClick={() => {
            console.log(`🎮 SimulationControls: Previous button clicked, current index: ${currentPhaseIndex}`);
            if (currentPhaseIndex === 0) {
              // On first scareware, go back to home page
              console.log(`🎮 SimulationControls: Going to home page`);
              onReset();
            } else {
              // Go to previous scareware
              const prevIndex = currentPhaseIndex - 1;
              console.log(`🎮 SimulationControls: Going to previous phase: ${phases[prevIndex].id}`);
              onAdvancePhase(phases[prevIndex].id as any);
            }
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#6c757d',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1,
            minWidth: '80px',
            transition: 'background-color 0.2s'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#5a6268';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = '#6c757d';
          }}
        >
          {currentPhaseIndex === 0 ? '← Return' : '← Previous'}
        </button>

        <button
          onClick={() => {
            console.log(`🎮 SimulationControls: Next button clicked, current index: ${currentPhaseIndex}`);
            if (currentPhaseIndex === phases.length - 1) {
              // On last scareware, go to escape guide
              console.log(`🎮 SimulationControls: Going to escape guide`);
              onAdvancePhase('escape' as any);
            } else {
              // Go to next scareware
              const nextIndex = currentPhaseIndex + 1;
              console.log(`🎮 SimulationControls: Going to next phase: ${phases[nextIndex].id}`);
              onAdvancePhase(phases[nextIndex].id as any);
            }
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1,
            minWidth: '80px',
            transition: 'background-color 0.2s'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#0056b3';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = '#007bff';
          }}
        >
          {currentPhaseIndex === phases.length - 1 ? 'Exit →' : 'Next →'}
        </button>
      </div>

      <div style={{ 
        marginTop: '0.5rem'
      }}>
        <button
          onClick={() => onAdvancePhase('escape' as any)}
          style={{
            padding: '0.5rem 1rem',
            background: '#28a745',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            width: '100%',
            transition: 'background-color 0.2s',
            marginBottom: '0.5rem'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#218838';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = '#28a745';
          }}
        >
          🛡️ Escape Guide
        </button>

        <button
          onClick={onReset}
          style={{
            padding: '0.5rem 1rem',
            background: '#dc3545',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            width: '100%',
            transition: 'background-color 0.2s'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#c82333';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = '#dc3545';
          }}
        >
          🏠 Exit to Home
        </button>
      </div>



      {/* Control switches for all phases */}
      <div style={{ 
        marginTop: '0.5rem'
      }}>
        {/* Norton escalation mode (only for Norton phase) */}
        {currentPhase === 'norton' && (
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'space-between',
            marginBottom: '0.5rem',
            padding: '0.5rem',
            background: 'rgba(220, 53, 69, 0.2)',
            borderRadius: '6px',
            border: '1px solid rgba(220, 53, 69, 0.4)'
          }}>
            <div style={{ fontSize: '0.9rem', fontWeight: 'bold', color: '#ff6b6b' }}>
              ⚡ Escalation Mode
            </div>
            <div
              onClick={() => {
                console.log('⏭️ Toggle Escalation switch clicked');
                if ((window as any).toggleNortonEscalation) {
                  (window as any).toggleNortonEscalation();
                } else {
                  console.log('⚠️ Toggle escalation function not available');
                }
              }}
              style={{
                width: '50px',
                height: '24px',
                background: nortonEscalation ? '#dc3545' : '#6c757d',
                borderRadius: '12px',
                cursor: 'pointer',
                position: 'relative',
                transition: 'background-color 0.3s ease',
                border: '2px solid #fff',
                boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
              }}
            >
              <div style={{
                width: '18px',
                height: '18px',
                background: '#fff',
                borderRadius: '50%',
                position: 'absolute',
                top: '1px',
                left: nortonEscalation ? '27px' : '1px',
                transition: 'left 0.3s ease',
                boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
              }} />
            </div>
          </div>
        )}

        {/* Speech toggle (available for all phases) */}
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          padding: '0.5rem',
          background: 'rgba(108, 117, 125, 0.2)',
          borderRadius: '6px',
          border: '1px solid rgba(108, 117, 125, 0.4)'
        }}>
          <div style={{ fontSize: '0.9rem', fontWeight: 'bold', color: '#b0b0b0' }}>
            🔊 Speech
          </div>
          <div
            onClick={() => {
              console.log('🔇 Toggle Speech switch clicked');
              toggleSpeech();
            }}
            style={{
              width: '50px',
              height: '24px',
              background: isPlaying ? '#28a745' : '#6c757d',
              borderRadius: '12px',
              cursor: 'pointer',
              position: 'relative',
              transition: 'background-color 0.3s ease',
              border: '2px solid #fff',
              boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
            }}
          >
            <div style={{
              width: '18px',
              height: '18px',
              background: '#fff',
              borderRadius: '50%',
              position: 'absolute',
              top: '1px',
              left: isPlaying ? '27px' : '1px',
              transition: 'left 0.3s ease',
              boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
            }} />
          </div>
        </div>
      </div>

      <div style={{ 
        marginTop: '1rem',
        padding: '0.75rem',
        background: 'rgba(0, 123, 255, 0.2)',
        borderRadius: '6px',
        border: '1px solid rgba(0, 123, 255, 0.4)',
        fontSize: '0.8rem',
        color: '#66b3ff'
      }}>
        <strong>💡 Note:</strong> All scareware buttons are safe to interact with in this educational simulation.
      </div>
        </>
      )}
    </div>
  );
};

export default SimulationControls;
